export const CENSUS_API_KEY_STORAGE = 'censusDataApiKey';

const ACS_YEAR = '2022';
const ACS_DATASET = 'acs/acs5';

/** ACS 5-year estimate variables (see Census variable definitions). */
export const ACS_VARIABLES = [
  { id: 'B01003_001E', label: 'Total population' },
  { id: 'B19013_001E', label: 'Median household income' },
  { id: 'B25077_001E', label: 'Median home value' },
  { id: 'B25001_001E', label: 'Total housing units' },
  { id: 'B25003_002E', label: 'Owner-occupied units' },
  { id: 'B25003_003E', label: 'Renter-occupied units' },
] as const;

export type CensusGeographyKind = 'zip' | 'county' | 'state';

export interface CensusGeographyQuery {
  kind: CensusGeographyKind;
  zip?: string;
  stateFips?: string;
  countyFips?: string;
}

export interface CensusDataRow {
  name: string;
  values: Record<string, string | number | null>;
}

export function loadStoredCensusApiKey(): string {
  try {
    return localStorage.getItem(CENSUS_API_KEY_STORAGE) ?? '';
  } catch {
    return '';
  }
}

export function saveStoredCensusApiKey(key: string): void {
  try {
    localStorage.setItem(CENSUS_API_KEY_STORAGE, key.trim());
  } catch {
    /* ignore */
  }
}

function buildGeographyClause(q: CensusGeographyQuery): string {
  if (q.kind === 'zip') {
    const zip = (q.zip ?? '').replace(/\D/g, '').slice(0, 5);
    if (zip.length !== 5) throw new Error('Enter a valid 5-digit ZIP code.');
    return `for=zip%20code%20tabulation%20area:${zip}`;
  }
  const state = (q.stateFips ?? '').replace(/\D/g, '').padStart(2, '0').slice(-2);
  if (state.length !== 2) throw new Error('Enter a 2-digit state FIPS code (e.g. 48 for Texas).');
  if (q.kind === 'state') {
    return `for=state:${state}`;
  }
  const county = (q.countyFips ?? '').replace(/\D/g, '').padStart(3, '0').slice(-3);
  if (county.length !== 3) throw new Error('Enter a 3-digit county FIPS code (e.g. 201 for Harris County, TX).');
  return `for=county:${county}&in=state:${state}`;
}

function formatCellValue(varId: string, raw: string): string | number | null {
  if (raw == null || raw === '' || raw === '-666666666' || raw === '-888888888' || raw === '-999999999') {
    return null;
  }
  const n = Number(raw);
  if (!Number.isFinite(n)) return raw;
  if (varId.includes('B19013') || varId.includes('B25077')) {
    return n;
  }
  return n;
}

export function formatCensusDisplayValue(varId: string, value: string | number | null): string {
  if (value == null) return '—';
  if (typeof value === 'number') {
    if (varId.includes('B19013') || varId.includes('B25077')) {
      return `$${value.toLocaleString(undefined, { maximumFractionDigits: 0 })}`;
    }
    return value.toLocaleString(undefined, { maximumFractionDigits: 0 });
  }
  return String(value);
}

export async function fetchAcs5Summary(
  apiKey: string,
  geography: CensusGeographyQuery
): Promise<CensusDataRow> {
  const key = apiKey.trim();
  if (!key) throw new Error('Add your Census API key below (stored only in this browser).');

  const vars = ['NAME', ...ACS_VARIABLES.map((v) => v.id)].join(',');
  const geo = buildGeographyClause(geography);
  const url = `https://api.census.gov/data/${ACS_YEAR}/${ACS_DATASET}?get=${vars}&${geo}&key=${encodeURIComponent(key)}`;

  const res = await fetch(url);
  if (!res.ok) {
    if (res.status === 401 || res.status === 403) {
      throw new Error('Census API rejected the key. Check your key at census.gov/developers.');
    }
    throw new Error(`Census API error (${res.status}).`);
  }

  const data = (await res.json()) as string[][];
  if (!Array.isArray(data) || data.length < 2) {
    throw new Error('No data returned for that geography. Check ZIP or FIPS codes.');
  }

  const headers = data[0];
  const row = data[1];
  const nameIdx = headers.indexOf('NAME');
  const name = nameIdx >= 0 ? row[nameIdx] : 'Area';

  const values: Record<string, string | number | null> = {};
  for (const v of ACS_VARIABLES) {
    const idx = headers.indexOf(v.id);
    values[v.id] = idx >= 0 ? formatCellValue(v.id, row[idx]) : null;
  }

  return { name: String(name), values };
}
