const parseMoney = (s: string): number => {
  const n = parseFloat(String(s).replace(/,/g, '').trim());
  return Number.isFinite(n) ? n : 0;
};

/** Default % of market value when generating offers */
export const DEFAULT_CASH1_PCT = 30;
export const DEFAULT_CASH2_PCT = 57.5;
export const DEFAULT_OWNER_FINANCE_PCT = 80;

export const CASH1_PCT_MIN = 0;
export const CASH1_PCT_MAX = 40;
export const CASH2_PCT_MIN = 50;
export const CASH2_PCT_MAX = 65;
export const OWNER_FINANCE_PCT_MIN = 65;
export const OWNER_FINANCE_PCT_MAX = 100;

export function parseMarketValueFromReport(text: string): number | null {
  const patterns = [
    /REAL PROPERTY MARKET VALUE:\s*\$?\s*([\d,]+(?:\.\d+)?)\s*\(\s*100\s*%\s*\)/i,
    /REAL PROPERTY MARKET VALUE:\s*\$?\s*([\d,]+(?:\.\d+)?)/i,
  ];
  for (const pattern of patterns) {
    const match = text.match(pattern);
    if (match) {
      const value = parseMoney(match[1]);
      if (value > 0) return value;
    }
  }
  return null;
}

export function parsePercentBand(text: string, percent: number): number | null {
  const re = new RegExp(String.raw`[•\-\*]?\s*${percent}\s*%\s*=\s*\$?\s*([\d,]+(?:\.\d+)?)`, 'i');
  const match = text.match(re);
  if (!match) return null;
  const value = parseMoney(match[1]);
  return value > 0 ? value : null;
}

export type LandOfferParseOutcome =
  | { ok: true; marketValue: number }
  | { ok: false; error: string };

export function parseMarketValueFromOfferReport(reportText: string): LandOfferParseOutcome {
  const text = reportText.trim();
  if (!text) {
    return { ok: false, error: 'Regenerate the report template from your comps first, then click Generate offer.' };
  }

  let marketValue = parseMarketValueFromReport(text);
  if (!marketValue) {
    for (const pct of [90, 80, 70, 65, 60, 50]) {
      const band = parsePercentBand(text, pct);
      if (band) {
        marketValue = band / (pct / 100);
        break;
      }
    }
  }
  if (!marketValue || marketValue <= 0) {
    return {
      ok: false,
      error:
        'Could not find REAL PROPERTY MARKET VALUE in the report. Regenerate the template from your comps or paste a complete summary.',
    };
  }

  return { ok: true, marketValue };
}

export const fmtOfferMoney = (n: number) =>
  n.toLocaleString(undefined, { maximumFractionDigits: 0 });

export function offerAmountFromMarket(marketValue: number, percent: number): number {
  return Math.round(marketValue * (percent / 100));
}

export function offerFormulaLine(marketValue: number, percent: number, amount: number): string {
  return `$${fmtOfferMoney(marketValue)} market value × ${percent}% = $${fmtOfferMoney(amount)}`;
}

export function calcMonthlyPayment(
  loanPrincipal: number,
  annualRatePct: number,
  months: number
): number {
  if (loanPrincipal <= 0 || months <= 0) return 0;
  const r = annualRatePct / 100 / 12;
  if (r === 0) {
    return loanPrincipal / months;
  }
  const pow = Math.pow(1 + r, months);
  return (loanPrincipal * r * pow) / (pow - 1);
}

export interface OwnerFinanceTerms {
  purchasePrice: number;
  downPayment: number;
  interestRatePct: number;
  /** Full amortization schedule length in years */
  termYears: number;
  balloonEnabled: boolean;
  /** Loan year (1, 2, 3…) when balloon balance is due */
  balloonDueYear: number;
}

export interface OwnerFinanceResult {
  amountFinanced: number;
  monthlyPayment: number;
  balloonBalance: number | null;
  balloonDueYear: number | null;
}

export function remainingBalanceAfterMonths(
  principal: number,
  annualRatePct: number,
  amortMonths: number,
  monthsPaid: number,
  monthlyPayment: number
): number {
  if (principal <= 0 || monthsPaid <= 0) return principal;
  const r = annualRatePct / 100 / 12;
  if (r === 0) {
    return Math.max(0, principal - monthlyPayment * monthsPaid);
  }
  const pow = Math.pow(1 + r, monthsPaid);
  return Math.max(0, principal * pow - monthlyPayment * ((pow - 1) / r));
}

export function ownerFinanceFromTerms(terms: OwnerFinanceTerms): OwnerFinanceResult {
  const amountFinanced = Math.max(0, terms.purchasePrice - terms.downPayment);
  const termMonths = Math.max(1, Math.round(terms.termYears * 12));
  const monthlyPayment = calcMonthlyPayment(
    amountFinanced,
    terms.interestRatePct,
    termMonths
  );

  if (!terms.balloonEnabled || terms.balloonDueYear < 1) {
    return {
      amountFinanced,
      monthlyPayment,
      balloonBalance: null,
      balloonDueYear: null,
    };
  }

  const monthsUntilBalloon = Math.round(terms.balloonDueYear * 12);
  const balloonBalance = remainingBalanceAfterMonths(
    amountFinanced,
    terms.interestRatePct,
    termMonths,
    monthsUntilBalloon,
    monthlyPayment
  );

  return {
    amountFinanced,
    monthlyPayment,
    balloonBalance,
    balloonDueYear: terms.balloonDueYear,
  };
}

export interface LandOffersSummaryInput {
  marketValue: number;
  cash1Pct: number;
  cash2Pct: number;
  ownerPct: number;
  ownerTerms: OwnerFinanceTerms;
  customizeOwnerTerms: boolean;
}

export function formatLandOffersSummary(input: LandOffersSummaryInput): string {
  const cash1 = offerAmountFromMarket(input.marketValue, input.cash1Pct);
  const cash2 = offerAmountFromMarket(input.marketValue, input.cash2Pct);
  const lines = [
    'LAND OFFERS (from evaluation report)',
    `Market value anchor: $${fmtOfferMoney(input.marketValue)}`,
    '',
    `Cash Offer 1 (${input.cash1Pct}%): $${fmtOfferMoney(cash1)}`,
    offerFormulaLine(input.marketValue, input.cash1Pct, cash1),
    '',
    `Cash Offer 2 (${input.cash2Pct}%): $${fmtOfferMoney(cash2)}`,
    offerFormulaLine(input.marketValue, input.cash2Pct, cash2),
    '',
    `Owner finance / creative (${input.ownerPct}% of market value):`,
    `  Total purchase price: $${fmtOfferMoney(input.ownerTerms.purchasePrice)}`,
  ];

  if (input.customizeOwnerTerms) {
    const finance = ownerFinanceFromTerms(input.ownerTerms);
    const detail: string[] = [];
    appendBalloonLines(detail, input.ownerTerms, finance);
    appendOwnerFinanceDetailLines(detail, input.ownerTerms, finance);
    lines.push(...detail.map((line) => `  ${line}`));
  } else {
    lines.push(
      `  (Use "Customize owner finance terms" in the calculator to add down payment, rate, and payments.)`
    );
  }

  return lines.join('\n');
}

/** Text for the Creative Offer field — owner finance only (no cash offers) */
export function formatCreativeOfferField(input: LandOffersSummaryInput): string {
  const finance = ownerFinanceFromTerms(input.ownerTerms);
  const lines = [
    `Creative / Owner Finance (65%–100% of est. market value):`,
    `Total purchase price: $${fmtOfferMoney(input.ownerTerms.purchasePrice)}`,
  ];

  if (input.customizeOwnerTerms) {
    appendBalloonLines(lines, input.ownerTerms, finance);
    appendOwnerFinanceDetailLines(lines, input.ownerTerms, finance);
  }

  return lines.join('\n');
}

function appendBalloonLines(
  lines: string[],
  terms: OwnerFinanceTerms,
  result: OwnerFinanceResult
): void {
  lines.push(`Balloon Payment? ${terms.balloonEnabled ? 'Yes' : 'No'}`);
  if (terms.balloonEnabled && result.balloonDueYear != null) {
    lines.push(`Balloon due: Year ${result.balloonDueYear}`);
    if (result.balloonBalance != null) {
      lines.push(`Estimated balloon balance: $${fmtOfferMoney(result.balloonBalance)}`);
    }
  }
}

function appendOwnerFinanceDetailLines(
  lines: string[],
  terms: OwnerFinanceTerms,
  result: OwnerFinanceResult
): void {
  lines.push(
    `Down payment: $${fmtOfferMoney(terms.downPayment)}`,
    `Amount financed: $${fmtOfferMoney(result.amountFinanced)}`,
    `Interest rate: ${terms.interestRatePct}%`,
    `Term: ${terms.termYears} years`
  );
  lines.push(`Estimated monthly payment: $${result.monthlyPayment.toFixed(2)}`);
}

/** @deprecated use parseMarketValueFromOfferReport */
export function generateLandOffersFromReport(reportText: string) {
  const outcome = parseMarketValueFromOfferReport(reportText);
  if (!outcome.ok) return { ok: false as const, error: outcome.error };
  const mv = outcome.marketValue;
  return {
    ok: true as const,
    offers: {
      marketValue: mv,
      cashOffer: {
        amount: offerAmountFromMarket(mv, DEFAULT_CASH1_PCT),
        percent: DEFAULT_CASH1_PCT,
        title: 'Cash Offer 1',
      },
      cashOffer2: {
        amount: offerAmountFromMarket(mv, DEFAULT_CASH2_PCT),
        percent: DEFAULT_CASH2_PCT,
        title: 'Cash Offer 2',
      },
      creativeOffer: {
        amount: offerAmountFromMarket(mv, DEFAULT_OWNER_FINANCE_PCT),
        percent: DEFAULT_OWNER_FINANCE_PCT,
        title: 'Owner Finance',
      },
    },
  };
}

export function formatLandOffersForClipboard(result: {
  marketValue: number;
  cashOffer: { amount: number; percent: number; title: string };
  cashOffer2: { amount: number; percent: number; title: string };
  creativeOffer: { amount: number; percent: number; title: string };
}): string {
  return formatLandOffersSummary({
    marketValue: result.marketValue,
    cash1Pct: result.cashOffer.percent,
    cash2Pct: result.cashOffer2.percent,
    ownerPct: result.creativeOffer.percent,
    customizeOwnerTerms: false,
    ownerTerms: {
      purchasePrice: result.creativeOffer.amount,
      downPayment: 0,
      interestRatePct: 0,
      termYears: 0,
      balloonEnabled: false,
      balloonDueYear: 0,
    },
  });
}
