import React, { useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  FormControl,
  InputLabel,
  MenuItem,
  Paper,
  Select,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TextField,
  Typography,
  CircularProgress,
} from '@mui/material';
import BarChartOutlinedIcon from '@mui/icons-material/BarChartOutlined';
import {
  ACS_VARIABLES,
  CensusGeographyKind,
  fetchAcs5Summary,
  formatCensusDisplayValue,
  loadStoredCensusApiKey,
  saveStoredCensusApiKey,
  type CensusDataRow,
} from './censusApi';

const CensusDataTab: React.FC = () => {
  const [apiKey, setApiKey] = useState('');
  const [apiKeyDraft, setApiKeyDraft] = useState('');
  const [geoKind, setGeoKind] = useState<CensusGeographyKind>('zip');
  const [zip, setZip] = useState('');
  const [stateFips, setStateFips] = useState('48');
  const [countyFips, setCountyFips] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [result, setResult] = useState<CensusDataRow | null>(null);

  useEffect(() => {
    const stored = loadStoredCensusApiKey();
    setApiKey(stored);
    setApiKeyDraft(stored);
  }, []);

  const handleSaveKey = () => {
    saveStoredCensusApiKey(apiKeyDraft);
    setApiKey(apiKeyDraft.trim());
  };

  const handleFetch = async () => {
    setError('');
    setResult(null);
    setLoading(true);
    try {
      const row = await fetchAcs5Summary(apiKey, {
        kind: geoKind,
        zip: geoKind === 'zip' ? zip : undefined,
        stateFips: geoKind !== 'zip' ? stateFips : undefined,
        countyFips: geoKind === 'county' ? countyFips : undefined,
      });
      setResult(row);
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Request failed.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <Box>
      <Paper sx={{ p: 3, mb: 3 }}>
        <Typography variant="h6" gutterBottom sx={{ display: 'flex', alignItems: 'center', gap: 1, fontWeight: 600 }}>
          <BarChartOutlinedIcon color="primary" />
          Census Data
        </Typography>
        <Typography variant="body2" color="text.secondary" paragraph>
          Pull U.S. Census Bureau ACS 5-year estimates (2022) for a ZIP code, county, or state. Useful for market context
          alongside land evaluation and amortization.
        </Typography>

        <Alert severity="info" sx={{ mb: 2 }}>
          Your Census API key is stored only in this browser (localStorage). Do not commit keys to GitHub. Get a free key at{' '}
          <Typography component="a" href="https://api.census.gov/data/key_signup.html" target="_blank" rel="noopener noreferrer">
            census.gov/developers
          </Typography>
          .
        </Alert>

        <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} sx={{ mb: 2 }} alignItems={{ sm: 'flex-end' }}>
          <TextField
            size="small"
            fullWidth
            label="Census API key"
            type="password"
            value={apiKeyDraft}
            onChange={(e) => setApiKeyDraft(e.target.value)}
            autoComplete="off"
          />
          <Button variant="outlined" onClick={handleSaveKey} sx={{ flexShrink: 0 }}>
            Save key
          </Button>
        </Stack>

        <FormControl size="small" fullWidth sx={{ mb: 2, maxWidth: 320 }}>
          <InputLabel>Geography</InputLabel>
          <Select
            label="Geography"
            value={geoKind}
            onChange={(e) => setGeoKind(e.target.value as CensusGeographyKind)}
          >
            <MenuItem value="zip">ZIP code (ZCTA)</MenuItem>
            <MenuItem value="county">County (state + county FIPS)</MenuItem>
            <MenuItem value="state">State (state FIPS)</MenuItem>
          </Select>
        </FormControl>

        {geoKind === 'zip' && (
          <TextField
            size="small"
            fullWidth
            label="ZIP code"
            value={zip}
            onChange={(e) => setZip(e.target.value)}
            inputProps={{ maxLength: 10 }}
            sx={{ mb: 2, maxWidth: 240 }}
            placeholder="77494"
          />
        )}

        {geoKind !== 'zip' && (
          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2} sx={{ mb: 2 }}>
            <TextField
              size="small"
              label="State FIPS"
              value={stateFips}
              onChange={(e) => setStateFips(e.target.value)}
              helperText="e.g. 48 = Texas"
              sx={{ maxWidth: 160 }}
            />
            {geoKind === 'county' && (
              <TextField
                size="small"
                label="County FIPS"
                value={countyFips}
                onChange={(e) => setCountyFips(e.target.value)}
                helperText="e.g. 201 = Harris County"
                sx={{ maxWidth: 200 }}
              />
            )}
          </Stack>
        )}

        <Button variant="contained" onClick={handleFetch} disabled={loading}>
          {loading ? <CircularProgress size={22} color="inherit" /> : 'Fetch Census data'}
        </Button>

        {error && (
          <Alert severity="warning" sx={{ mt: 2 }}>
            {error}
          </Alert>
        )}
      </Paper>

      {result && (
        <Paper sx={{ p: 3 }}>
          <Typography variant="subtitle1" fontWeight={600} gutterBottom>
            {result.name}
          </Typography>
          <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 2 }}>
            Source: ACS 5-year estimates (2022), U.S. Census Bureau
          </Typography>
          <TableContainer>
            <Table size="small">
              <TableHead>
                <TableRow>
                  <TableCell>Metric</TableCell>
                  <TableCell align="right">Estimate</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {ACS_VARIABLES.map((v) => (
                  <TableRow key={v.id}>
                    <TableCell>{v.label}</TableCell>
                    <TableCell align="right">
                      {formatCensusDisplayValue(v.id, result.values[v.id] ?? null)}
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        </Paper>
      )}
    </Box>
  );
};

export default CensusDataTab;
