import React, { useEffect, useMemo, useState } from 'react';
import {
  Box,
  FormControl,
  FormControlLabel,
  FormLabel,
  Grid,
  Radio,
  RadioGroup,
  Slider,
  Switch,
  TextField,
  Typography,
} from '@mui/material';
import { alpha, useTheme, type Theme } from '@mui/material/styles';
import {
  CASH1_PCT_MAX,
  CASH1_PCT_MIN,
  CASH2_PCT_MAX,
  CASH2_PCT_MIN,
  DEFAULT_CASH1_PCT,
  DEFAULT_CASH2_PCT,
  DEFAULT_OWNER_FINANCE_PCT,
  OWNER_FINANCE_PCT_MAX,
  OWNER_FINANCE_PCT_MIN,
  fmtOfferMoney,
  formatCreativeOfferField,
  offerAmountFromMarket,
  offerFormulaLine,
  ownerFinanceFromTerms,
} from './landOfferFromReport';

interface LandOfferResultsPanelProps {
  marketValue: number;
  onSummaryChange?: (summary: string) => void;
}

type BubbleColor = 'green' | 'orange' | 'purple';

function offerBubbleStyles(theme: Theme, color: BubbleColor) {
  const isDark = theme.palette.mode === 'dark';
  const specs: Record<
    BubbleColor,
    { accent: string; bg: string; heading: string; amount: string; slider: string }
  > = {
    green: {
      accent: theme.palette.success.main,
      bg: isDark ? alpha(theme.palette.success.main, 0.16) : '#e8f5e9',
      heading: isDark ? theme.palette.success.light : theme.palette.success.dark,
      amount: isDark ? theme.palette.success.light : theme.palette.success.dark,
      slider: theme.palette.success.main,
    },
    orange: {
      accent: theme.palette.warning.main,
      bg: isDark ? alpha(theme.palette.warning.main, 0.16) : '#fff3e0',
      heading: isDark ? theme.palette.warning.light : '#e65100',
      amount: isDark ? theme.palette.warning.light : '#e65100',
      slider: theme.palette.warning.main,
    },
    purple: {
      accent: isDark ? '#b39ddb' : '#5e35b1',
      bg: isDark ? alpha('#b39ddb', 0.14) : '#ede7f6',
      heading: isDark ? theme.palette.text.primary : '#4527a0',
      amount: isDark ? theme.palette.text.primary : '#4527a0',
      slider: isDark ? '#b39ddb' : '#5e35b1',
    },
  };
  const s = specs[color];
  return {
    box: {
      borderRadius: 3,
      p: 2.5,
      mb: 2,
      bgcolor: s.bg,
      border: `2px solid ${alpha(s.accent, isDark ? 0.45 : 0.35)}`,
      boxShadow: isDark ? 'none' : `0 4px 14px ${alpha(s.accent, 0.12)}`,
    },
    heading: s.heading,
    amount: s.amount,
    slider: s.slider,
    accent: s.accent,
  };
}

const LandOfferResultsPanel: React.FC<LandOfferResultsPanelProps> = ({
  marketValue,
  onSummaryChange,
}) => {
  const theme = useTheme();
  const green = offerBubbleStyles(theme, 'green');
  const orange = offerBubbleStyles(theme, 'orange');
  const purple = offerBubbleStyles(theme, 'purple');

  const [cash1Pct, setCash1Pct] = useState(DEFAULT_CASH1_PCT);
  const [cash2Pct, setCash2Pct] = useState(DEFAULT_CASH2_PCT);
  const [ownerPct, setOwnerPct] = useState(DEFAULT_OWNER_FINANCE_PCT);
  const [customizeOwnerTerms, setCustomizeOwnerTerms] = useState(false);

  const [purchasePrice, setPurchasePrice] = useState(
    offerAmountFromMarket(marketValue, DEFAULT_OWNER_FINANCE_PCT)
  );
  const [downPayment, setDownPayment] = useState(0);
  const [interestRatePct, setInterestRatePct] = useState(0);
  const [termYears, setTermYears] = useState(30);
  const [balloonEnabled, setBalloonEnabled] = useState(false);
  const [balloonDueYear, setBalloonDueYear] = useState(5);

  useEffect(() => {
    setCash1Pct(DEFAULT_CASH1_PCT);
    setCash2Pct(DEFAULT_CASH2_PCT);
    setOwnerPct(DEFAULT_OWNER_FINANCE_PCT);
    const pp = offerAmountFromMarket(marketValue, DEFAULT_OWNER_FINANCE_PCT);
    setPurchasePrice(pp);
    setDownPayment(0);
    setInterestRatePct(0);
    setTermYears(30);
    setBalloonEnabled(false);
    setBalloonDueYear(5);
    setCustomizeOwnerTerms(false);
  }, [marketValue]);

  useEffect(() => {
    setPurchasePrice(offerAmountFromMarket(marketValue, ownerPct));
  }, [marketValue, ownerPct]);

  const cash1Amount = offerAmountFromMarket(marketValue, cash1Pct);
  const cash2Amount = offerAmountFromMarket(marketValue, cash2Pct);

  const ownerTerms = useMemo(
    () => ({
      purchasePrice,
      downPayment,
      interestRatePct,
      termYears,
      balloonEnabled,
      balloonDueYear: balloonEnabled ? Math.max(1, balloonDueYear) : 0,
    }),
    [purchasePrice, downPayment, interestRatePct, termYears, balloonEnabled, balloonDueYear]
  );

  const finance = ownerFinanceFromTerms(ownerTerms);
  const { amountFinanced, monthlyPayment, balloonBalance, balloonDueYear: dueYear } = finance;

  useEffect(() => {
    onSummaryChange?.(
      formatCreativeOfferField({
        marketValue,
        cash1Pct,
        cash2Pct,
        ownerPct,
        ownerTerms,
        customizeOwnerTerms,
      })
    );
  }, [
    marketValue,
    cash1Pct,
    cash2Pct,
    ownerPct,
    ownerTerms,
    customizeOwnerTerms,
    onSummaryChange,
  ]);

  const pctLabel = (value: number) => `${value}%`;

  return (
    <Box sx={{ mt: 2 }}>
      <Typography variant="subtitle1" fontWeight={600} gutterBottom>
        Your offers (based on market value)
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
        Est. market value (from your comps):{' '}
        <Typography component="span" fontWeight={700} color="text.primary">
          ${fmtOfferMoney(marketValue)}
        </Typography>
        . Adjust each slider to update offer amounts.
      </Typography>

      <Box sx={green.box}>
        <Typography variant="overline" fontWeight={700} sx={{ color: green.heading }}>
          Cash Offer 1 · 0%–40% of market value
        </Typography>
        <Typography variant="h4" fontWeight={700} sx={{ my: 0.5, color: green.amount }}>
          ${fmtOfferMoney(cash1Amount)}
        </Typography>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 1.5 }}>
          {offerFormulaLine(marketValue, cash1Pct, cash1Amount)}
        </Typography>
        <Slider
          value={cash1Pct}
          min={CASH1_PCT_MIN}
          max={CASH1_PCT_MAX}
          step={1}
          valueLabelDisplay="on"
          valueLabelFormat={pctLabel}
          color="success"
          onChange={(_, v) => setCash1Pct(v as number)}
          marks={[
            { value: 0, label: '0%' },
            { value: 40, label: '40%' },
          ]}
        />
      </Box>

      <Box sx={orange.box}>
        <Typography variant="overline" fontWeight={700} sx={{ color: orange.heading }}>
          Cash Offer 2 · 50%–65% of market value
        </Typography>
        <Typography variant="h4" fontWeight={700} sx={{ my: 0.5, color: orange.amount }}>
          ${fmtOfferMoney(cash2Amount)}
        </Typography>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 1.5 }}>
          {offerFormulaLine(marketValue, cash2Pct, cash2Amount)}
        </Typography>
        <Slider
          value={cash2Pct}
          min={CASH2_PCT_MIN}
          max={CASH2_PCT_MAX}
          step={0.5}
          valueLabelDisplay="on"
          valueLabelFormat={pctLabel}
          onChange={(_, v) => setCash2Pct(v as number)}
          sx={{
            color: orange.slider,
            '& .MuiSlider-thumb': { borderColor: orange.slider },
          }}
          marks={[
            { value: 50, label: '50%' },
            { value: 65, label: '65%' },
          ]}
        />
      </Box>

      <Box sx={purple.box}>
        <Typography variant="overline" fontWeight={700} sx={{ color: purple.heading }}>
          Creative / Owner Finance · 65%–100% of market value
        </Typography>
        <Typography variant="h4" fontWeight={700} sx={{ my: 0.5, color: purple.amount }}>
          ${fmtOfferMoney(purchasePrice)}
        </Typography>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 1.5 }}>
          Total purchase price at {ownerPct}% of ${fmtOfferMoney(marketValue)} market value
        </Typography>
        <Slider
          value={ownerPct}
          min={OWNER_FINANCE_PCT_MIN}
          max={OWNER_FINANCE_PCT_MAX}
          step={1}
          valueLabelDisplay="on"
          valueLabelFormat={pctLabel}
          onChange={(_, v) => setOwnerPct(v as number)}
          sx={{
            color: purple.slider,
            mb: 1,
          }}
          marks={[
            { value: 65, label: '65%' },
            { value: 100, label: '100%' },
          ]}
        />

        <FormControlLabel
          control={
            <Switch
              checked={customizeOwnerTerms}
              onChange={(e) => {
                const on = e.target.checked;
                setCustomizeOwnerTerms(on);
                if (on) {
                  setTermYears(30);
                  setInterestRatePct(0);
                  setDownPayment(0);
                }
              }}
              color="primary"
            />
          }
          label="Customize owner finance terms"
        />

        {customizeOwnerTerms ? (
          <>
          <Grid container spacing={2} sx={{ mt: 0.5 }}>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                size="small"
                label="Total purchase price"
                type="number"
                value={purchasePrice}
                onChange={(e) => setPurchasePrice(Math.max(0, Number(e.target.value) || 0))}
                helperText="Usually tied to % slider above; edit if needed"
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                size="small"
                label="Down payment"
                type="number"
                value={downPayment}
                onChange={(e) => setDownPayment(Math.max(0, Number(e.target.value) || 0))}
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                size="small"
                label="Interest rate (%)"
                type="number"
                inputProps={{ step: 0.125, min: 0 }}
                value={interestRatePct}
                onChange={(e) => setInterestRatePct(Math.max(0, Number(e.target.value) || 0))}
              />
              <FormControl component="fieldset" variant="standard" fullWidth sx={{ mt: 2 }}>
                <FormLabel
                  component="legend"
                  sx={{ fontSize: '0.875rem', color: purple.heading, fontWeight: 600 }}
                >
                  Balloon Payment?
                </FormLabel>
                <RadioGroup
                  row
                  value={balloonEnabled ? 'yes' : 'no'}
                  onChange={(e) => setBalloonEnabled(e.target.value === 'yes')}
                >
                  <FormControlLabel
                    value="yes"
                    control={<Radio size="small" sx={{ color: purple.slider }} />}
                    label="Yes"
                  />
                  <FormControlLabel
                    value="no"
                    control={<Radio size="small" sx={{ color: purple.slider }} />}
                    label="No"
                  />
                </RadioGroup>
              </FormControl>
              {balloonEnabled && (
                <TextField
                  fullWidth
                  size="small"
                  label="Balloon due (year)"
                  type="number"
                  inputProps={{ min: 1, step: 1 }}
                  value={balloonDueYear}
                  onChange={(e) => setBalloonDueYear(Math.max(1, Number(e.target.value) || 1))}
                  helperText="Loan year when the balloon payment is due (e.g. 5 = end of year 5)"
                  sx={{ mt: 1 }}
                />
              )}
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                size="small"
                label="Term (years)"
                type="number"
                inputProps={{ min: 1, step: 1 }}
                value={termYears}
                onChange={(e) => setTermYears(Math.max(1, Number(e.target.value) || 1))}
                helperText="Full amortization schedule length"
              />
            </Grid>
          </Grid>

          <Box
            sx={{
              mt: 2,
              p: 2,
              borderRadius: 2,
              bgcolor: alpha(purple.accent, theme.palette.mode === 'dark' ? 0.12 : 0.08),
              border: `1px solid ${alpha(purple.accent, 0.25)}`,
            }}
          >
            <Typography variant="body2" color="text.secondary">
              Amount financed:{' '}
              <Typography component="span" fontWeight={700} color="text.primary">
                ${fmtOfferMoney(amountFinanced)}
              </Typography>
            </Typography>
            <Typography variant="h6" color="text.primary" sx={{ mt: 0.5 }}>
              Est. monthly payment: ${monthlyPayment.toFixed(2)}
            </Typography>
            {balloonEnabled && dueYear != null && balloonBalance != null && (
              <Typography variant="body2" color="text.primary" sx={{ mt: 1 }}>
                Balloon due Year {dueYear}:{' '}
                <Typography component="span" fontWeight={700}>
                  ${fmtOfferMoney(balloonBalance)}
                </Typography>
              </Typography>
            )}
            <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 0.5 }}>
              {balloonEnabled
                ? `Payment based on a ${termYears}-year schedule; balloon balance due in year ${balloonDueYear}.`
                : `Fixed-rate, fully amortizing payment over ${termYears} years.`}
            </Typography>
          </Box>
          </>
        ) : null}
      </Box>
    </Box>
  );
};

export default LandOfferResultsPanel;
